using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Input;
namespace Pharmacie.Wpf;
public class MainWindow:Window{readonly PharmacyData data;readonly StackPanel content=new();readonly TextBlock title=new();readonly Brush teal=new SolidColorBrush(Color.FromRgb(32,162,138));readonly Brush navy=new SolidColorBrush(Color.FromRgb(13,45,57));List<Product> cart=[];
public MainWindow(){data=DataStore.Load();Title="PharmaFlow - Gestion de pharmacie";Width=1200;Height=760;WindowStartupLocation=WindowStartupLocation.CenterScreen;BuildShell();ShowHome();}
void BuildShell(){var root=new Grid();root.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(235)});root.ColumnDefinitions.Add(new ColumnDefinition());var menu=new StackPanel{Margin=new Thickness(18)};menu.Children.Add(new TextBlock{Text="✚ PharmaFlow",Foreground=Brushes.White,FontSize=22,FontWeight=FontWeights.Bold,Margin=new Thickness(0,8,0,30)});AddMenu(menu,"Tableau de bord",ShowDashboard);AddMenu(menu,"Produits",ShowProducts);AddMenu(menu,"Vente & caisse",ShowSale);AddMenu(menu,"Stocks & approvisionnement",ShowStock);AddMenu(menu,"Rapports",ShowReports);AddMenu(menu,"Paramètres",()=>Simple("Paramètres"));root.Children.Add(new Border{Background=navy,Child=menu});var right=new Grid();right.RowDefinitions.Add(new RowDefinition{Height=new GridLength(74)});right.RowDefinitions.Add(new RowDefinition());title.Text="Tableau de bord";title.FontSize=21;title.FontWeight=FontWeights.Bold;title.VerticalAlignment=VerticalAlignment.Center;title.Margin=new Thickness(30,0,0,0);right.Children.Add(new Border{Background=Brushes.White,Child=title});var scroll=new ScrollViewer{Content=content,Margin=new Thickness(30)};Grid.SetRow(scroll,1);right.Children.Add(scroll);Grid.SetColumn(right,1);root.Children.Add(right);Content=root;}
void AddMenu(Panel p,string text,Action action){var b=new Button{Content=text,Padding=new Thickness(13),Margin=new Thickness(0,4,0,4),HorizontalContentAlignment=HorizontalAlignment.Left,Foreground=Brushes.White,Background=Brushes.Transparent,BorderBrush=Brushes.Transparent,FontSize=14};b.MouseEnter+=(s,e)=>b.Background=new SolidColorBrush(Color.FromArgb(45,255,255,255));b.MouseLeave+=(s,e)=>b.Background=Brushes.Transparent;b.Click+=(s,e)=>action();p.Children.Add(b);}
TextBlock T(string s,int n=16)=>new(){Text=s,FontSize=n,Margin=new Thickness(0,6,0,6)};void Clear(string t){title.Text=t;content.Children.Clear();}
Border Card(string l,string v){var st=new StackPanel();st.Children.Add(T(l,13));st.Children.Add(new TextBlock{Text=v,FontSize=24,FontWeight=FontWeights.Bold,Foreground=teal,Margin=new Thickness(0,8,0,0)});return new Border{Child=st,Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,234,236)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Padding=new Thickness(18),Margin=new Thickness(0,0,14,14),Width=210};}
Button Action(string text,RoutedEventHandler click,bool primary=true){var b=new Button{Content=text,Padding=new Thickness(13,9,13,9),Margin=new Thickness(0,5,8,5),Background=primary?teal:Brushes.White,Foreground=primary?Brushes.White:navy,BorderBrush=primary?teal:new SolidColorBrush(Color.FromRgb(210,220,223)),BorderThickness=new Thickness(1),FontWeight=FontWeights.Bold};b.Click+=click;b.MouseEnter+=(s,e)=>b.Opacity=.8;b.MouseLeave+=(s,e)=>b.Opacity=1;return b;}
void ShowHome(){Clear("Accueil");content.Children.Add(T("Pharmacie La Santé",34));content.Children.Add(T("Bienvenue dans PharmaFlow",24));content.Children.Add(T("Gérez vos produits, vos stocks et vos ventes depuis une seule application.",17));content.Children.Add(Action("Accéder au tableau de bord",(s,e)=>ShowDashboard()));content.Children.Add(T("Résumé rapide",22));content.Children.Add(T($"{data.Products.Count} produits enregistrés   |   {data.Sales.Count} ventes   |   {data.Products.Count(p=>p.Stock<=p.Minimum)} alertes stock",17));}void ShowDashboard(){Clear("Tableau de bord");content.Children.Add(T("Bonjour Alain,",29));content.Children.Add(T("Vue d’ensemble de votre pharmacie",15));var row=new WrapPanel{Margin=new Thickness(0,20,0,15)};row.Children.Add(Card("Produits actifs",data.Products.Count.ToString()));row.Children.Add(Card("Ruptures",data.Products.Count(p=>p.Stock==0).ToString()));row.Children.Add(Card("Ventes enregistrées",data.Sales.Count.ToString()));row.Children.Add(Card("Chiffre d’affaires",$"{data.Sales.Sum(s=>s.Total):N0} FCFA"));content.Children.Add(row);content.Children.Add(T("Alertes",20));foreach(var p in data.Products.Where(p=>p.Stock<=p.Minimum))content.Children.Add(T($"⚠ {p.Name} : {p.Status} ({p.Stock} unité(s))",15));}
void ShowProducts(){Clear("Produits");content.Children.Add(T("Catalogue des produits",27));var bar=new StackPanel{Orientation=Orientation.Horizontal};var search=new TextBox{Width=330,Padding=new Thickness(10),ToolTip="Rechercher un produit"};bar.Children.Add(search);bar.Children.Add(Action("＋ Ajouter un produit",(s,e)=>AddProductForm(),true));content.Children.Add(bar);var grid=new DataGrid{ItemsSource=data.Products,AutoGenerateColumns=true,IsReadOnly=true,Height=330,Margin=new Thickness(0,15,0,0)};search.TextChanged+=(s,e)=>grid.ItemsSource=data.Products.Where(p=>p.Name.Contains(search.Text,StringComparison.OrdinalIgnoreCase)||p.Reference.Contains(search.Text,StringComparison.OrdinalIgnoreCase));content.Children.Add(grid);}
void AddProductForm(){Clear("Ajouter un produit");content.Children.Add(T("Nouveau produit",25));var name=new TextBox{Margin=new Thickness(0,5,0,5),Padding=new Thickness(10)};var reference=new TextBox{Margin=new Thickness(0,5,0,5),Padding=new Thickness(10)};var price=new TextBox{Margin=new Thickness(0,5,0,5),Padding=new Thickness(10)};var stock=new TextBox{Margin=new Thickness(0,5,0,5),Padding=new Thickness(10)};content.Children.Add(T("Désignation"));content.Children.Add(name);content.Children.Add(T("Référence"));content.Children.Add(reference);content.Children.Add(T("Prix de vente"));content.Children.Add(price);content.Children.Add(T("Stock initial"));content.Children.Add(stock);content.Children.Add(Action("Enregistrer le produit",(s,e)=>{if(string.IsNullOrWhiteSpace(name.Text)||!decimal.TryParse(price.Text,out var pr)||!int.TryParse(stock.Text,out var st)){MessageBox.Show("Veuillez remplir correctement les champs.");return;}data.Products.Add(new Product{Reference=reference.Text,Name=name.Text,Price=pr,Stock=st,Minimum=5,Lot="LOT-INITIAL",Expiry=DateTime.Today.AddYears(1)});DataStore.Save(data);MessageBox.Show("Produit ajouté.");ShowProducts();}));}
void ShowSale(){Clear("Vente & caisse");content.Children.Add(T("Produits disponibles",25));var layout=new DockPanel();var cartPanel=new StackPanel{Width=330,Margin=new Thickness(20,0,0,0)};DockPanel.SetDock(cartPanel,Dock.Right);cartPanel.Children.Add(T("Panier",20));var totalText=new TextBlock{FontSize=20,FontWeight=FontWeights.Bold,Foreground=teal};cartPanel.Children.Add(totalText);cartPanel.Children.Add(Action("Valider la vente",(s,e)=>{if(cart.Count==0)return;foreach(var p in cart)p.Stock--;var total=cart.Sum(p=>p.Price);data.Sales.Add(new Sale{Number="V-"+(data.Sales.Count+1001),Date=DateTime.Now,Total=total,Payment="Espèces"});DataStore.Save(data);cart.Clear();MessageBox.Show("Vente validée et stock mis à jour.");ShowSale();}));cartPanel.Children.Add(Action("Vider le panier",(s,e)=>{cart.Clear();ShowSale();},false));layout.Children.Add(cartPanel);var productsPanel=new WrapPanel();foreach(var p in data.Products.Where(p=>p.Stock>0)){var b=Action($"{p.Name}\n{p.Price:N0} FCFA | stock {p.Stock}",(s,e)=>{cart.Add(p);totalText.Text=$"Total : {cart.Sum(x=>x.Price):N0} FCFA";},false);b.Width=240;productsPanel.Children.Add(b);}layout.Children.Add(productsPanel);content.Children.Add(layout);}
void ShowStock(){Clear("Stocks & approvisionnement");content.Children.Add(T("Réceptions et inventaire",26));content.Children.Add(Action("＋ Réceptionner 10 unités",(s,e)=>{if(data.Products.Count>0)data.Products[0].Stock+=10;DataStore.Save(data);ShowStock();}));content.Children.Add(Action("Valider l’inventaire",(s,e)=>{DataStore.Save(data);MessageBox.Show("Inventaire sauvegardé.");},false));content.Children.Add(new DataGrid{ItemsSource=data.Products,AutoGenerateColumns=true,IsReadOnly=true,Height=300,Margin=new Thickness(0,12,0,0)});}
void ShowReports(){Clear("Rapports");content.Children.Add(T("Rapport des ventes",26));content.Children.Add(T($"Chiffre d’affaires : {data.Sales.Sum(s=>s.Total):N0} FCFA",20));content.Children.Add(new DataGrid{ItemsSource=data.Sales,AutoGenerateColumns=true,IsReadOnly=true,Height=300});}void Simple(string t){Clear(t);content.Children.Add(T($"Module {t} prêt à être complété.",22));}}



